macro_rules! deps {
    () => {
        Version!();
        VersionReq!();
    };
}

macro_rules! BuildMetadata {
    () => {
        deps!();
        # [doc = " Optional build metadata identifier. This comes after `+` in a SemVer"] # [doc = " version, as in `0.8.1+zstd.1.5.0`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Some real world build metadata idioms drawn from crates.io:"] # [doc = ""] # [doc = " - **[libgit2-sys]** <code>0.12.20+<b>1.1.0</b></code> &mdash; for this"] # [doc = "   crate, the build metadata indicates the version of the C libgit2 library"] # [doc = "   that the Rust crate is built against."] # [doc = ""] # [doc = " - **[mashup]** <code>0.1.13+<b>deprecated</b></code> &mdash; just the word"] # [doc = "   \"deprecated\" for a crate that has been superseded by another. Eventually"] # [doc = "   people will take notice of this in Cargo's build output where it lists the"] # [doc = "   crates being compiled."] # [doc = ""] # [doc = " - **[google-bigquery2]** <code>2.0.4+<b>20210327</b></code> &mdash; this"] # [doc = "   library is automatically generated from an official API schema, and the"] # [doc = "   build metadata indicates the date on which that schema was last captured."] # [doc = ""] # [doc = " - **[fbthrift-git]** <code>0.0.6+<b>c7fcc0e</b></code> &mdash; this crate is"] # [doc = "   published from snapshots of a big company monorepo. In monorepo"] # [doc = "   development, there is no concept of versions, and all downstream code is"] # [doc = "   just updated atomically in the same commit that breaking changes to a"] # [doc = "   library are landed. Therefore for crates.io purposes, every published"] # [doc = "   version must be assumed to be incompatible with the previous. The build"] # [doc = "   metadata provides the source control hash of the snapshotted code."] # [doc = ""] # [doc = " [libgit2-sys]: https://crates.io/crates/libgit2-sys"] # [doc = " [mashup]: https://crates.io/crates/mashup"] # [doc = " [google-bigquery2]: https://crates.io/crates/google-bigquery2"] # [doc = " [fbthrift-git]: https://crates.io/crates/fbthrift-git"] # [doc = ""] # [doc = " # Syntax"] # [doc = ""] # [doc = " Build metadata is a series of dot separated identifiers immediately"] # [doc = " following the patch or pre-release version. Identifiers must comprise only"] # [doc = " ASCII alphanumerics and hyphens: `0-9`, `A-Z`, `a-z`, `-`. Identifiers must"] # [doc = " not be empty. Leading zeros *are* allowed, unlike any other place in the"] # [doc = " SemVer grammar."] # [doc = ""] # [doc = " # Total ordering"] # [doc = ""] # [doc = " Build metadata is ignored in evaluating `VersionReq`; it plays no role in"] # [doc = " whether a `Version` matches any one of the comparison operators."] # [doc = ""] # [doc = " However for comparing build metadatas among one another, they do have a"] # [doc = " total order which is determined by lexicographic ordering of dot-separated"] # [doc = " components. Identifiers consisting of only digits are compared numerically."] # [doc = " Otherwise, identifiers are compared in ASCII sort order. Any numeric"] # [doc = " identifier is always less than any non-numeric identifier."] # [doc = ""] # [doc = " Example:&ensp;`demo`&ensp;&lt;&ensp;`demo.85`&ensp;&lt;&ensp;`demo.90`&ensp;&lt;&ensp;`demo.090`&ensp;&lt;&ensp;`demo.200`&ensp;&lt;&ensp;`demo.1a0`&ensp;&lt;&ensp;`demo.a`&ensp;&lt;&ensp;`memo`"] # [derive (Default , Clone , Eq , PartialEq , Hash)] pub struct BuildMetadata { identifier : Identifier , }
    };
}

BuildMetadata!()